<?php
namespace App\Http\Controllers;use App\Models\Project;use App\Services\ExcelImportService;use Illuminate\Http\Request;class ImportController extends Controller{function index(){return view('imports.index',['projects'=>Project::all()]);}function run(Request $r,ExcelImportService $s){$r->validate(['advance_file'=>'nullable|file','timesheet_file'=>'nullable|file','project_id'=>'nullable','month'=>'required','year'=>'required']);$a=$r->file('advance_file')?->store('imports');$t=$r->file('timesheet_file')?->store('imports');$p=Project::find($r->project_id)?->name?:'WADI SAFAR';$sum=$s->import($a?storage_path('app/'.$a):null,$t?storage_path('app/'.$t):null,$p,(int)$r->month,(int)$r->year,auth()->id());return back()->with('success','Import done: '.json_encode($sum));}function preview(){return back()->with('success','Files look valid.');}}
